{'role': 'user', 'content': [{'tool_use_id': 'toolu_01SjaafwD6YuzpcMws1VozrC', 'type': 'tool_result', 'content': '     1→import { useState, useCallback } from "react";
     2→import { useTrackAnalysis } from "../../api/tracks";
