    12→
    13→export function AnalysisViewer({ fingerprint }: AnalysisViewerProps) {
    14→  const { data: analysis, isLoading, error } = useTrackAnalysis(fingerprint);
    15→
    16→  const duration = analysis?.duration ?? 0;
    17→  const { viewStart, viewEnd, setView, zoomToSection } = useWaveformView(duration);
    18→
    19→  const [highlightedSection, setHighlightedSection] = useState<number | null>(null);
    20→  const [selectedSection, setSelectedSection] = useState<number | null>(null);
    21→
    22→  // Waveform -> Section list: hover
    23→  const handleWaveformSectionHover = useCallback((index: number | null) => {
    24→    setHighlightedSection(index);
    25→  }, []);
    26→
    27→  // Waveform -> Section list: click
    28→  const handleWaveformSectionClick = useCallback((index: number) => {
    29→    setSelectedSection(index);
    30→  }, []);
    31→
    32→  // Section list -> Waveform: hover
    33→  const handleListHover = useCallback((index: number | null) => {
    34→    setHighlightedSection(index);
    35→  }, []);
    36→
    37→  // Section list -> Waveform: click (zoom to section)
