    53→  if (isLoading) {
    54→    return (
    55→      <div className="mt-4 h-40 bg-gray-900 rounded border border-gray-800 animate-pulse" />
    56→    );
    57→  }
    58→
    59→  if (!analysis) return null;
    60→
    61→  return (
    62→    <div className="mt-4 space-y-4">
    63→      {/* Waveform */}
    64→      {analysis.waveform ? (
    65→        <WaveformCanvas
