    71→          selectedSection={selectedSection}
    72→          onSectionHover={handleWaveformSectionHover}
    73→          onSectionClick={handleWaveformSectionClick}
    74→          viewStart={viewStart}
    75→          viewEnd={viewEnd}
    76→          onViewChange={setView}
    77→        />
    78→      ) : (
    79→        <div className="h-40 flex items-center justify-center bg-gray-950 rounded border border-gray-800">
    80→          <p className="text-gray-500 text-sm">No waveform data — re-analyze with waveform enabled</p>
    81→        </div>
    82→      )}
    83→
    84→      {/* Bottom grid: section list | metadata | placeholders */}
    85→      <div className="grid grid-cols-1 lg:grid-cols-3 gap-4">
    86→        <div>
    87→          <SectionList
    88→            sections={analysis.sections}
    89→            highlightedIndex={highlightedSection}
    90→            selectedIndex={selectedSection}
    91→            onHover={handleListHover}
    92→            onSelect={handleListSelect}
    93→          />
    94→        </div>
    95→
    96→        <div>
    97→          <TrackMetadataPanel analysis={analysis} />
    98→        </div>
