{'role': 'user', 'content': [{'tool_use_id': 'toolu_01WNde38FXcmeJy9ZWrWrT7V', 'type': 'tool_result', 'content': '     1→import { useMemo } from "react";
     2→import { WaveformCanvas } from "../shared/WaveformCanvas";
     3→import type { TrackAnalysis } from "../../types";
     4→
     5→const WINDOW_SECONDS = 12;
     6→
     7→export interface DeckWaveformProps {
     8→  analysis: TrackAnalysis;
     9→  /** Current playback position in milliseconds, or null when stopped. */
    10→  positionMs: number | null;
    11→}
    12→
    13→export function DeckWaveform({ analysis, positionMs }: DeckWaveformProps) {
    14→  const cursorSec = positionMs !== null ? positionMs / 1000 : null;
    15→  const { duration, sections } = analysis;
    16→
    17→  const { viewStart, viewEnd } = useMemo(() => {
    18→    if (cursorSec === null) {
    19→      return { viewStart: 0, viewEnd: Math.min(WINDOW_SECONDS, duration) };
    20→    }
    21→    const half = WINDOW_SECONDS / 2;
    22→    const start = Math.max(0, cursorSec - half);
    23→    const end = Math.min(duration, cursorSec + half);
    24→    return { viewStart: start, viewEnd: end };
    25→  }, [cursorSec, duration]);
    26→
    27→  const currentSectionIndex = useMemo(() => {
    28→    if (cursorSec === null || !sections) return null;
    29→    const idx = sections.findIndex(
    30→      (s) => cursorSec >= s.start && cursorSec < s.end,
    31→    );
    32→    return idx >= 0 ? idx : null;
    33→  }, [cursorSec, sections]);
    34→
    35→  return (
    36→    <WaveformCanvas
    37→      waveform={analysis.waveform}
    38→      sections={sections}
    39→      duration={duration}
    40→      viewStart={viewStart}
    41→      viewEnd={viewEnd}
    42→      cursorPosition={cursorSec}
    43→      highlightedSection={currentSectionIndex}
    44→      selectedSection={null}
    45→    />
    46→  );
    47→}
    48→'}]}

